      `).join('')}
    </div>
    <div class="nav-tools">
      <button onclick="toggleFontSize()">字号 ${localStorage.getItem('fontSize') || '中'}</button>
      <button onclick="toggleVertical()">${localStorage.getItem('vertical') === 'true' ? '横排' : '竖排'}</button>
    </div>
  `;
